package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="notification_outbox") public class NotificationOutbox{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="event_type",nullable=false,length=60) private String eventType;@Column(name="entity_type",nullable=false,length=40) private String entityType;@Column(name="entity_id",nullable=false) private UUID entityId;@Column(name="recipient_role",nullable=false,length=60) private String recipientRole;@Column(nullable=false,length=200) private String subject;@Column(nullable=false,length=1000) private String message;@Column(nullable=false,length=20) private String status="PENDING";@Column(name="created_at",nullable=false) private Instant createdAt;@Column(name="sent_at") private Instant sentAt;@PrePersist void create(){createdAt=Instant.now();}public void setEventType(String v){eventType=v;}public void setEntityType(String v){entityType=v;}public void setEntityId(UUID v){entityId=v;}public void setRecipientRole(String v){recipientRole=v;}public void setSubject(String v){subject=v;}public void setMessage(String v){message=v;}}
